SET structured_content = json_set(
  structured_content,
  '$.value', '{"agencyName":"Holidays Hunt","tagline":"Expert in Kashmir & Himachal Tours • India''s Trusted Holiday & Tour Facilitator","email":"info@holidayshunt.com","phone":"+91 94199 15255","whatsapp":"+919419915255","address":"Holidays Hunt Travel & Hospitality Pvt Ltd, Boulevard / Rajbagh, Srinagar, Kashmir / Katra / New Delhi","currencySymbol":"₹","taxRegistrationNumber":"GSTIN: 07AAACH9921M1Z4","bankName":"HDFC Bank Ltd.","accountName":"Holidays Hunt","accountNumber":"50200099887766","ifscCode":"HDFC0000456","upiId":"holidayshunt@hdfcbank","invoicePrefix":"HH-2026-","voucherPrefix":"VOU-HH-","invoiceTerms":["1. 25% Advance payment required to confirm hotel reservations and dedicated vehicle booking.","2. Balance payment must be settled before check-in or commencement of sightseeing as per voucher.","3. All inclusions are clearly stated in the official tour voucher.","4. AC operates in plain areas and will be switched off on hilly drives for vehicle safety.","5. 24x7 guest support team and emergency assistance available throughout the trip."],"faqs":[{"id":"faq-1","question":"What destinations does Holidays Hunt specialize in?","answer":"Holidays Hunt specializes in Jammu & Kashmir and Himachal Pradesh holidays, including Kashmir, Jammu, Gulmarg, Pahalgam, Sonamarg, Doodhpathri, Katra, Shimla, Manali, Dharamshala, Dalhousie and nearby destinations."},{"id":"faq-2","question":"Can Holidays Hunt customize a Jammu & Kashmir tour for my family?","answer":"Yes. We can customize the duration, sightseeing, hotel category, vehicle and pace of your Jammu & Kashmir trip based on your family size, travel dates and preferences."},{"id":"faq-3","question":"Can I combine Kashmir and Himachal Pradesh in one trip?","answer":"Yes. We can plan a combined Jammu & Kashmir and Himachal Pradesh itinerary when your travel dates allow enough time for the journey. The route can be designed around your preferred destinations and pace."},{"id":"faq-4","question":"Which places can I cover in a Kashmir tour?","answer":"Popular Kashmir itineraries include Srinagar, Gulmarg, Pahalgam, Sonamarg and Doodhpathri. We can also add a houseboat stay, Shikara ride or other experiences according to your interests."},{"id":"faq-5","question":"Which Himachal destinations does Holidays Hunt cover?","answer":"Our Himachal tours can include Shimla, Kufri, Manali, Solang Valley, Atal Tunnel, Dharamshala, McLeod Ganj, Palampur, Dalhousie, Khajjiar, Kangra and other destinations based on your itinerary."},{"id":"faq-6","question":"What type of hotels and vehicles are available?","answer":"We offer different hotel categories and private vehicle options depending on the destination, group size and budget. The recommended hotels and vehicle type are clearly shared before booking."},{"id":"faq-7","question":"Is a private cab available for Jammu, Kashmir and Himachal tours?","answer":"Yes. Private cabs with experienced local drivers can be arranged for airport or railway transfers, intercity travel and sightseeing across Jammu & Kashmir and Himachal Pradesh, subject to the selected itinerary."},{"id":"faq-8","question":"How does Holidays Hunt help senior citizens and families?","answer":"We plan practical travel schedules, comfortable hotel stays and suitable private transport. We can also reduce long sightseeing days and adjust the itinerary to make the journey more comfortable for senior citizens and families."},{"id":"faq-9","question":"What is the payment and booking process?","answer":"Once you approve the itinerary and quotation, the required advance payment is collected to confirm the selected hotels and vehicle. The exact payment schedule and booking terms are shared with the quotation and booking confirmation."},{"id":"faq-10","question":"What is the cancellation policy for Holidays Hunt tours?","answer":"Cancellation charges depend on the travel date, hotel and service providers involved in the booking. The applicable cancellation terms are shared with your quotation or booking confirmation before you make the payment."}],"footerMenus":[{"id":"fm-discover","title":"DISCOVER US","items":[{"id":"fmi-about","label":"About us","url":"about"},{"id":"fmi-careers","label":"Careers","url":"careers"},{"id":"fmi-contact","label":"Contact us","url":"locate_us"},{"id":"fmi-faq","label":"FAQ","url":"faq"},{"id":"fmi-guide","label":"Guide","url":"guide"},{"id":"fmi-sitemap","label":"Sitemap","url":"sitemap"}]},{"id":"fm-yatras","title":"SACRED YATRAS","items":[{"id":"fmi-vd","label":"Vaishno Devi Yatra","url":"pilgrimage"},{"id":"fmi-hd","label":"Himachal Devi Darshan","url":"pilgrimage"},{"id":"fmi-fam","label":"Family Devotional Tours","url":"family"}]},{"id":"fm-tours","title":"TOP TOURS","items":[{"id":"fmi-t-kashmir","label":"Kashmir Paradise","url":"kashmir"},{"id":"fmi-t-himachal","label":"Himachal Mountains","url":"himachal"},{"id":"fmi-t-vaishno","label":"Mata Vaishno Devi","url":"jammu"},{"id":"fmi-t-hd","label":"Himachal Devi Darshan","url":"himachal_devi"}]},{"id":"fm-security","title":"SECURITY & TRUST","items":[{"id":"fmi-terms","label":"Terms & Conditions","url":"terms"},{"id":"fmi-cancel","label":"Cancellation Policy","url":"cancellation"},{"id":"fmi-privacy","label":"Privacy Policy","url":"privacy"},{"id":"fmi-sec","label":"100% Verified Stays","url":"security"}]}],"bottomNavItems":[{"id":"bnav-explore","label":"Explore","icon":"home","actionType":"home","enabled":true},{"id":"bnav-tours","label":"Tours","icon":"tours","actionType":"tours","badge":"count","enabled":true},{"id":"bnav-destinations","label":"Destinations","icon":"destinations","actionType":"destinations","enabled":true},{"id":"bnav-chat","label":"Chat","icon":"chat","actionType":"whatsapp","enabled":true}],"sacredMantra":"","updatedAt":"2026-09-25T20:12:40.827Z"}'
